static void journey_rect(float x,float y,float w,float h,int r,int gg,int b,int a){SDL_SetRenderDrawColor(renderer,r,gg,b,a);SDL_FRect d=camera_rect((SDL_FRect){x*3,y*3,w*3,h*3});SDL_RenderFillRect(renderer,&d);}
static void journey_line(float x,float y,float xx,float yy,int r,int gg,int b,int a){SDL_SetRenderDrawColor(renderer,r,gg,b,a);x*=3;y*=3;xx*=3;yy*=3;camera_point(&x,&y);camera_point(&xx,&yy);SDL_RenderLine(renderer,x,y,xx,yy);}
static void journey_cell(SDL_Texture*t,int col,int row,int cols,int rows,float x,float y,float w,float h){nquad=0;quad((x-w/2)*3,(y-h/2)*3,w*3,h*3,(SDL_FColor){1,1,1,1},col/(float)cols,row/(float)rows,1.0f/cols,1.0f/rows);flush(t);}
static int journey_plate(void){switch(journey_kind()){case ENV_OCEAN:return 0;case ENV_WRECK:return 1;case ENV_HIVE:case ENV_ROOT:return 2;case ENV_BEAST:case ENV_TEETH:return 3;case ENV_BASE:case ENV_REACTOR:case ENV_ESCAPE:return 4;case ENV_ICE:case ENV_BLIZZARD:return 5;}return -1;}
static void draw_journey_world(void){SDL_Rect clip={0,72,960,696};SDL_SetRenderClipRect(renderer,&clip);int p=journey_plate(),k=journey_kind();
 if(p>=0){/* Edge-inset UVs, mirrored horizontal repeats and feathered row overlaps. */float speed=k==ENV_OCEAN?35:70,scroll=fmodf(backgroundClock*speed,696),tw,th;SDL_GetTextureSize(journeyPlates,&tw,&th);float angle=flight_view_angle(),fieldW=960-264*sideBlend,cover=fmaxf(1,(960*fabsf(cosf(angle))+696*fabsf(sinf(angle)))/fieldW)*1.04f,tileW=960*cover,z=ex.giant.active?journeyZoom:1;float u=(p%3)/3.0f+4/tw,vv=(p/3)/2.0f+4/th,uw=1/3.0f-8/tw,vh=1/2.0f-8/th;int span=ex.giant.active?2:0;for(int col=-span;col<=span;col++)for(int n=-2;n<=2;n++){float y=72+scroll+n*696,x=480-tileW/2+col*tileW,uu=u,du=uw;if(abs(col)&1){uu+=du;du=-du;}nquad=0;quad(x,y,tileW,72,(SDL_FColor){.7f,.75f,.8f,1},uu,vv,du,vh*72/768);vertices[0].color.a=vertices[1].color.a=0;quad(x,y+72,tileW,696,(SDL_FColor){.7f,.75f,.8f,1},uu,vv+vh*72/768,du,vh*696/768);float w=(960-264*sideBlend)*z,h=(696+264*sideBlend)*z;for(int v=0;v<nquad*4;v++){float xx=(vertices[v].position.x-480)*w/960,yy=(vertices[v].position.y-420)*h/696;vertices[v].position.x=480+xx*cosf(angle)-yy*sinf(angle);vertices[v].position.y=420+xx*sinf(angle)+yy*cosf(angle);}lastGroundDX=-sinf(angle)*backgroundClock*speed*h/696;lastGroundDY=cosf(angle)*backgroundClock*speed*h/696;flush(journeyPlates);}}
 if(k==ENV_SKY||k==ENV_OCEAN||k==ENV_EM){/* Share terrain's screen-space flight vector; no separate left/down overlay. */float foreground=ex.phase==10?1000:90;SDL_SetTextureBlendMode(cloudTexture,SDL_BLENDMODE_BLEND);SDL_SetTextureColorMod(cloudTexture,190,215,235);scrolling_layer(cloudTexture,foreground,1.6f,70,1);scrolling_layer(cloudTexture,foreground*1.6f,1.15f,55,1);}
 draw_storm_rain();
 SDL_SetRenderClipRect(renderer,0);
}
/* Hull can extend beyond the collision field. Its components are drawn in that field. */
static void draw_giant_form(int form,float opacity){if(opacity<=0)return;int m=journey_number();float a=flight_view_angle(),w=(960-264*sideBlend)*journeyZoom,h=(696+264*sideBlend)*journeyZoom,scale=giant_world_scale();SDL_Texture*t=form?giantForms:giantHulls;float uv[4]={(m%3)/3.0f,(m/3)/2.0f,1/3.0f,1/2.0f};if(form)memcpy(uv,giantFormsUV[form-1][m],sizeof(uv));nquad=0;quad((160+giant_body_shift()*scale-176*scale)*3,(100-96*scale)*3,1056*scale,576*scale,(SDL_FColor){1,1,1,opacity},uv[0],uv[1],uv[2],uv[3]);for(int v=0;v<nquad*4;v++){float xx=(vertices[v].position.x-480)*w/960,yy=(vertices[v].position.y-420)*h/696;vertices[v].position.x=480+xx*cosf(a)-yy*sinf(a);vertices[v].position.y=420+xx*sinf(a)+yy*cosf(a);}flush(t);}
static void draw_giant_backdrop(void){Giant*b=&ex.giant;if(!b->active||b->archetype==4)return;SDL_Rect clip={0,72,960,696};SDL_SetRenderClipRect(renderer,&clip);float t=b->morph?giant_morph_fraction():1;if(b->morph)draw_giant_form(b->oldForm,1-t);draw_giant_form(b->form,t);SDL_SetRenderClipRect(renderer,0);}
static void draw_worm_form(GiantPart*p,int i,int form,float alpha){if(alpha<=0)return;float ww,hh;SDL_GetTextureSize(wormTexture,&ww,&hh);int col=i==6?0:i==8?2:1;const float*uv=wormFormsUV[form][col];SDL_FRect src={uv[0]*ww,uv[1]*hh,uv[2]*ww,uv[3]*hh},dst={(p->x-p->w/2)*3,(p->y-p->h/2)*3,p->w*3,p->h*3};dst=camera_rect(dst);SDL_SetTextureAlphaMod(wormTexture,(Uint8)(255*alpha));SDL_RenderTextureRotated(renderer,wormTexture,&src,&dst,p->angle,0,SDL_FLIP_NONE);if(boss_flash_alpha(p->damageUntil)){SDL_SetTextureAlphaMod(wormDamage,(Uint8)(255*alpha*boss_flash_alpha(p->damageUntil)));SDL_RenderTextureRotated(renderer,wormDamage,&src,&dst,p->angle,0,SDL_FLIP_NONE);}SDL_SetTextureAlphaMod(wormTexture,255);}
static void draw_giant_module(GiantPart*p,int i){Giant*b=&ex.giant;int m=b->archetype,row=i==6?2:i>=2&&i<6?1:0,custom=(i>=7&&b->form>=2)||(i>=4&&i<6&&b->form>=1);float uv[4]={m/6.0f,row/3.0f,1/6.0f,1/3.0f};if(custom)memcpy(uv,giantModuleUV[i>=7?1:0][m],sizeof(uv));if(custom&&(i&1)){uv[0]+=uv[2];uv[2]=-uv[2];}float alpha=b->morph&&custom?giant_morph_fraction():1;for(int pass=0;pass<2;pass++){float opacity=pass?boss_flash_alpha(p->damageUntil):1;if(!opacity)continue;nquad=0;quad((p->x-p->w*.5f)*3,(p->y-p->h*.5f)*3,p->w*3,p->h*3,(SDL_FColor){1,1,1,alpha*opacity},uv[0],uv[1],uv[2],uv[3]);flush(custom?(pass?moduleDamage:giantModules):(pass?partDamage:giantParts));}}
#include "giant_tactics_render.h"
static void draw_journey_combat(void){SDL_SetRenderDrawBlendMode(renderer,SDL_BLENDMODE_BLEND);int k=journey_kind(),t=ex.env.timer;SDL_Rect clip={0,72,960,696};SDL_SetRenderClipRect(renderer,&clip);
 if(k==ENV_BASE){Bombing*b=&ex.bombing;for(int i=0;i<8;i++){GroundTarget*t=b->targets+i;if(t->hp<=0)continue;int shield=bombing_shielded(i);journey_cell(giantParts,5,t->role==1?0:t->role==2?2:1,6,3,t->x,t->y,32,32);journey_rect(t->x-16,t->y-20,32*t->hp/(float)t->maxHp,2,shield?80:140,shield?170:255,shield?255:130,230);if(shield){nquad=0;quad((t->x-24)*3,(t->y-24)*3,144,144,(SDL_FColor){.1f,.5f,1,.25f},0,0,1,1);flush(halo);}}for(int n=0;n<12;n++){GroundPayload*p=b->bombs+n;if(!p->on)continue;int x=p->x/Q,y=p->y/Q;pc_equipment_sprite(115,x,y,0);journey_line(x,y+5,x,y+16,255,145,30,200);}if(!b->complete){for(int y=40;y<240;y+=28){int x=160+(sn((b->timer+(220-y)*3)/2+b->pass*37)*36>>10);journey_line(x-4,y+3,x,y-3,150,230,200,100);journey_line(x,y-3,x+4,y+3,150,230,200,100);}}}
 if(k==ENV_ROOT){for(int y=30;y<250;y+=32){int l=tunnel_left(y),r=tunnel_right(y);journey_cell(worldObjects,1,1,4,2,l-8,y,38,44);journey_cell(worldObjects,1,1,4,2,r+8,y,38,44);}}
 if(k==ENV_WALL)draw_fine_terrain();

 if(k==ENV_MOUTH||k==ENV_TEETH){int gate=k==ENV_MOUTH?(t-100)*3/5-40:(t-400)*3/5-40;journey_cell(mawTexture,0,0,1,1,160,gate+18,360,220);journey_rect(116,gate-8,88,3,90,255,190,200);}
 if(k==ENV_ESCAPE){int gate=(t-400)*3/5-40;for(int x=0;x<320;x+=16)if(x<112||x>=208)journey_cell(worldObjects,2,0,4,2,x+8,gate+9,18,22);journey_line(115,gate,115,gate+35,90,255,190,220);journey_line(205,gate,205,gate+35,90,255,190,220);}
 if(k==ENV_OCEAN&&t>=500&&t<1000){int y=t<650?30:t-700;int gap=ex.env.safeX;if(t<650){journey_rect(0,y,320,3,90,215,255,80);}else{int left=gap-44,right=320-gap-44;if(left>0)journey_cell(worldObjects,2,1,4,2,left*.5f,y,left,70);if(right>0)journey_cell(worldObjects,2,1,4,2,gap+44+right*.5f,y,right,70);}journey_line(gap-44,30,gap-44,255,80,255,190,110);journey_line(gap+44,30,gap+44,255,80,255,190,110);}
 for(int i=0;i<32;i++){EnvironmentHazard*h=ex.env.hazards+i;if(!h->on)continue;int x=h->x/Q,y=h->y/Q;if(h->type>=20&&h->type<=25){if(h->type==24)journey_cell(parasiteTexture,2,0,4,1,x,y,28,28);else journey_cell(giantParts,h->type-20,1,6,3,x,y,28,28);journey_line(x-16,y-16,x+16,y-16,255,90,200,255);journey_line(x-16,y+16,x+16,y+16,255,90,200,255);continue;}if(h->type==12){journey_cell(parasiteTexture,3,0,4,1,x,y,30,36);if(h->age>=120)journey_rect(x-16,y-22,32,3,170,255,90,220);continue;}if(h->type==13){journey_line(x,y-8,x,y+6,130,255,70,240);journey_rect(x-1,y-2,2,5,200,255,110,230);continue;}if(h->type==14){nquad=0;quad((x-17)*3,(y-20)*3,102,120,(SDL_FColor){1,.25f,.025f,.9f},0,0,1,1);flush(halo);journey_cell(worldObjects,0,1,4,2,x,y,28,34);continue;}if(h->type>=9){journey_cell(parasiteTexture,h->type-9,0,4,1,x,y,h->type==11?25:20,20);continue;}if(h->type==4){journey_cell(worldObjects,1,0,4,2,x,y,h->r*2.5f,h->r*2.5f);continue;}int col=h->type>=6?5:h->type==1?1:h->type==3?4:h->type==4?3:h->type==5?2:0;journey_cell(giantParts,col,h->type==6?1:0,6,3,x,y,h->r*2,h->r*2);if(h->type==8){nquad=0;quad((x-h->r-4)*3,(y-h->r-4)*3,(h->r*2+8)*3,(h->r*2+8)*3,(SDL_FColor){.1f,.8f,1,.2f},0,0,1,1);flush(halo);}}
 if(ex.env.warning==1||ex.env.warning==6){int x=ex.env.strikeX;journey_rect(x-(ex.env.warning==6?33:2),24,ex.env.warning==6?66:4,232,160,215,255,50);}
 if(t%600>=475&&t%600<487&&(k==ENV_SKY||k==ENV_OCEAN||k==ENV_WRECK||k==ENV_REACTOR)){int x=ex.env.strikeX;for(int y=24;y<256;y+=12){journey_line(x,y,x+((y&16)?5:-5),y+12,220,245,255,255);}}
 if(ex.env.warning==2||ex.env.empActive){journey_rect(0,24,320,232,100,35,150,ex.env.empActive?35:12);for(int y=30;y<256;y+=28)journey_line(0,y,320,y+8,150,110,255,45);}
 if(ex.env.warning==19||ex.env.warning==20){journey_rect(0,24,94,232,60,170,35,ex.env.warning==19?15:50);journey_rect(226,24,94,232,60,170,35,ex.env.warning==19?15:50);journey_line(115,24,115,256,160,250,100,130);journey_line(205,24,205,256,160,250,100,130);}if(ex.env.warning==21)journey_rect(ex.env.strikeX-36,24,72,232,255,120,30,35);
 if(ex.env.cutter)journey_rect(g.px/Q-1,player_y/Q-100,2,90,100,255,200,220);
 Giant*b=&ex.giant;if(b->active){int a=b->archetype;draw_giant_tactics();
 if(a==4){for(int side=0;side<2;side++){int y=b->form==0?100:b->form==1?(side?70:145):(side?155:80);int x=side?tunnel_right(y)+2:tunnel_left(y)-2;journey_cell(worldObjects,3,1,4,2,x,y,36,52);}}
  for(int i=0;i<9;i++){GiantPart*p=b->parts+i;if(!p->hp||(a==4&&!p->visible))continue;int open=giant_open(i);if(a==4){float t=b->morph?giant_morph_fraction():1;if(b->morph)draw_worm_form(p,i,b->oldForm,1-t);draw_worm_form(p,i,b->form,t);}else draw_giant_module(p,i);if(!open){nquad=0;quad((p->x-p->w*.7f)*3,(p->y-p->h*.7f)*3,p->w*4.2f,p->h*4.2f,(SDL_FColor){.15f,.5f,1,.2f},0,0,1,1);flush(halo);}else{journey_line(p->x-p->w/2,p->y+p->h/2,p->x+p->w/2,p->y+p->h/2,140,255,170,230);}journey_rect(p->x-p->w/2,p->y-p->h/2-4,p->w*p->hp/(float)p->maxHp,2,open?110:80,open?255:160,open?130:255,240);}
 }
 SDL_SetRenderClipRect(renderer,0);
}

static void draw_journey_attached(void){for(int e=0;e<MAXE;e++)if(g.enemies[e].on&&g.enemies[e].dotTicks){nquad=0;quad(g.enemies[e].x/Q*3-36,g.enemies[e].y/Q*3-36,72,72,(SDL_FColor){.2f,.5f,1,.35f},0,0,1,1);flush(halo);}if(ex.repairFlash){nquad=0;quad(g.px/Q*3-70,player_y/Q*3-70,140,140,(SDL_FColor){.1f,1,.65f,ex.repairFlash/80.0f},0,0,1,1);flush(halo);}for(int i=0;i<ex.leeches;i++)journey_cell(parasiteTexture,i%2,0,4,1,parasite_x(i),parasite_y(i),11,12);if(journey_kind()==ENV_BEAST&&ex.env.timer%500>=400){int c=ex.env.timer%500;journey_rect(125,24,70,232,110,170,255,c<475?25:80);journey_line(125,24,125,256,130,220,255,170);journey_line(195,24,195,256,130,220,255,170);if(c>=475)for(int y=30;y<256;y+=16)journey_line(130+(y%7),y,190-(y%11),y+16,200,245,255,240);}}
